//! Independent endpoint-antiderivative fixtures and actual Young/source bounds.
use algorithmic_gas_benchmarks::{
    convergence_chapter06_completion::*, convergence_chapter06_source_moment::*,
    convergence_landscape_axioms::*,
};

#[test]
fn native_energy_matches_independent_endpoint_primitives_in_cancellation_regimes() {
    // 70-digit endpoint primitive fixtures, generated by the separate Python review.
    for (left, right, expected) in [
        (vec![0.1], vec![0.10000000001], 1378.7584374422545),
        (vec![0.25], vec![0.25], 4010.9236135075394),
        (vec![-1., 0.3], vec![2., -0.9], 4094.8625509278872),
        (vec![-1e-6], vec![1e-6], 5.247922745244712e-8),
    ] {
        let (observed, _) = rastrigin_segment_energy(&left, &right, 8192).unwrap();
        assert!((observed - expected).abs() <= 2e-11 * expected.max(1.));
        let (reversed, _) = rastrigin_segment_energy(&right, &left, 8192).unwrap();
        assert!((observed - reversed).abs() < 1e-10);
    }
}

#[test]
fn source_pressure_bound_covers_exact_frozen_nonlinear_gate_without_labels() {
    let mut source = SourceMomentParameters {
        position_feature_radius: 2.,
        velocity_feature_radius: 2.,
        algorithmic_velocity_weight: 1.,
        cloning_bandwidth: 3.,
        gate_saturation: 1.,
        gate_epsilon: 1e-6,
        historical_window: 0,
        component_collision_enabled: true,
        fitness_channels: vec![
            FitnessChannelRange {
                amplitude: 2.,
                positive_floor: 0.1,
                exponent: 1e-5,
            };
            2
        ],
    };
    let certificate = source_moment_envelope(&source).unwrap();
    assert!((certificate.acceptance_upper - 6.089224172042453e-5).abs() < 1e-15);
    let low = certificate.log_fitness_lower.exp();
    let high = certificate.log_fitness_upper.exp();
    for n in [2, 4, 16, 64] {
        let positions: Vec<f64> = (0..n)
            .map(|j| if j % 3 == 0 { 100. } else { 0.01 })
            .collect();
        let fitness: Vec<f64> = (0..n)
            .map(|j| if j % 3 == 0 { high } else { low })
            .collect();
        let moment = positions.iter().map(|x| x.powi(4)).sum::<f64>() / n as f64;
        let mut expected = moment;
        for i in 0..n {
            // Unequal admissible weights correlated with physical moment/fitness.
            let weights: Vec<f64> = (0..n)
                .map(|j| {
                    if i == j {
                        0.
                    } else if j % 3 == 0 {
                        1.
                    } else {
                        certificate.kernel_lower_float
                    }
                })
                .collect();
            let normalizer = weights.iter().sum::<f64>();
            for j in 0..n {
                let acceptance =
                    ((fitness[j] - fitness[i]) / (fitness[i] + source.gate_epsilon)).clamp(0., 1.);
                expected += weights[j] / normalizer
                    * acceptance
                    * (positions[j].powi(4) - positions[i].powi(4))
                    / n as f64;
            }
        }
        assert!(expected <= certificate.current_frame_source_moment_coefficient * moment + 1e-8);
        // Duplication changes this finite proposal, but not the certified constant.
        assert!(expected >= moment);
    }
    // Native component collisions reject historical accepted edges, even at
    // zero restitution. The source theorem must preserve that capability gate.
    source.historical_window = 1;
    assert!(source_moment_envelope(&source).is_err());
    source.component_collision_enabled = false;
    assert!(source_moment_envelope(&source).is_ok());
}

#[test]
fn young_constant_bounds_continuum_of_actual_source_moments() {
    for p in [1.1, 2., 4., 8.] {
        let params = NativeTailParameters {
            dimension: 2,
            moment_order: p,
            timestep: 0.04,
            friction: 1.,
            harmonic_curvature: 2.,
            residual_per_coordinate: 20. * std::f64::consts::PI,
            clone_jitter_standard_deviation: 0.1,
            ou_standard_deviation: ((1. - (-0.08_f64).exp()) / 2.).sqrt(),
            final_position_standard_deviation: 0.02,
            frozen_velocity_norm_bound: 2.,
            restitution: 0.5,
        };
        for exponent in -8..=14 {
            let input = 10_f64.powi(exponent);
            let budget = native_selected_source_tail_interface(&params, input).unwrap();
            let affine = budget.source_moment_coefficient * input + budget.drift_additive_moment;
            assert!(budget.one_step_moment_upper <= affine * (1. + 2e-13));
        }
        if p == 4. {
            let budget = native_selected_source_tail_interface(&params, 1.).unwrap();
            assert!((budget.source_moment_coefficient - 0.9968701109956499).abs() < 2e-15);
            assert!((budget.drift_additive_moment / 29385514.228489637 - 1.).abs() < 2e-11);
        }
    }
}
